{
  "chapter_proposals": [
    {
      "chapter_id": "CH1",
      "title": "物理界限：色散工程中的延迟 - 带宽积与视场饱和效应",
      "purpose": "本章旨在建立可见光消色差超构透镜性能的根本物理约束，通过量化分析澄清‘大视场必然导致带宽线性崩溃’的常见误区。核心任务是推导并解释延迟 - 带宽积（Delay-Bandwidth Product）如何作为局部超表面的基本限制，并揭示有限孔径效应导致的‘带宽饱和’现象，从而为后续章节的设计机制分析确立理论天花板。",
      "scope": "严格限定于基于局部相位调控（传播延迟或共振相位）的单层平面超构透镜。重点分析数值孔径（NA）与半视场角（FOV）对最大可用带宽的联合约束。涵盖两种焦点映射几何（无畸变 tan(α) 与线性 α）下的理论差异。明确排除多元件复合系统、纯衍射能量重分配方案以及非局部（non-local）超表面结构的详细讨论，仅将其作为背景提及以界定本章模型的适用边界。",
      "excluded_source_handles": [],
      "substantive_threads": [
        {
          "theme": "延迟 - 带宽积作为基本物理约束",
          "argumentation_flow": "首先引入 P0002 的核心推导，将每个超构原子建模为一维延迟线，确立局部相互作用下的基本不等式 ΔT · Δω ≤ κ。论证最大群延迟范围（ΔT_max）直接决定了可用带宽的上限。指出在消色差设计中，为了补偿不同波长下的相位差，所需的群延迟跨度随 NA 增加而急剧扩大，这是高 NA 器件带宽受限的首要原因。",
          "evidence_base": ["P0002"],
          "conditions_and_limits": "该推导基于标量近似和局部相位假设。在极高 NA 或亚波长尺度下，矢量衍射效应可能引入修正，但定性趋势（带宽随 NA 减小）保持不变。"
        },
        {
          "theme": "群延迟需求的非单调性与带宽饱和机制",
          "argumentation_flow": "深入分析有限孔径金属透镜上群延迟分布的空间特性。反驳直觉认为‘入射角越大，所需相位/群延迟补偿越大’的观点。基于 P0002 的数值结果，阐述随着视场角（FOV）增加，透镜面上所需的最大群延迟差值先增大，在特定临界角（α*）达到峰值，随后在接近掠射角时因有效孔径截断和光程差变化率降低而减小。由此论证‘带宽饱和’现象：当工作 FOV 超过覆盖 α* 的临界值后，决定带宽下限的 ΔT_max 不再随 FOV 增加而显著增加，导致带宽界限趋于稳定而非无限下降。",
          "evidence_base": ["P0002"],
          "conditions_and_limits": "饱和点的具体位置依赖于 NA 值和焦点定义方式。此结论修正了简单的线性衰退预期，表明在大视场区域存在优化的理论空间。"
        },
        {
          "theme": "焦点几何映射对带宽界限的影响",
          "argumentation_flow": "对比两种常见的焦点定位策略：r0 = F tan(α)（无畸变成像）与 r0 = F α（线性映射，存在畸变）。分析显示，虽然两种几何配置下计算出的绝对带宽数值存在差异（无畸变要求通常更严苛），但‘随 FOV 增加而饱和’这一核心物理趋势在两种情况下均稳健存在。这表明饱和现象是有限孔径系统的内禀属性，而非特定成像标准的产物。",
          "evidence_base": ["P0002"],
          "conditions_and_limits": "实际应用中需根据成像质量要求（是否容忍畸变）选择对应的理论界限作为参考，但两者均受同一饱和机制支配。"
        },
        {
          "theme": "单界面几何像差的独立硬限制",
          "argumentation_flow": "结合 P0001 的视角，指出即使色散被完美校正（即满足上述带宽界限），单层超构透镜仍受限于单界面几何无法校正高阶像差（如彗差、像散、场曲）。特别是在高 NA（如 NA=0.5）条件下，这些几何像差在大视场（>5 µm 线度）下会迅速破坏衍射极限成像。这构成了 FOV 的另一重硬性限制，独立于色散工程的带宽限制之外，解释了为何单纯优化色散不足以实现宽视场高性能成像。",
          "evidence_base": ["P0001", "P0002"],
          "conditions_and_limits": "此限制针对单层结构；多层或复合系统可缓解此问题，但不在本章主要讨论范围内。"
        }
      ],
      "transition_logic": "在确立了由物理定律决定的带宽与视场理论天花板后，本章揭示了‘大视场并非绝对禁区’的微妙物理图像。然而，理论上的可能性并不等同于工程实现的易行性。为了逼近这些理论极限，设计者必须采用特定的纳米结构来提供所需的巨大群延迟范围。下一章（CH2）将深入微观层面，剖析为了实现这种色散补偿，波导型与共振型设计机制是如何引入新的效率损耗，特别是斜入射条件下的模式耦合与效率崩溃机制，从而连接宏观物理界限与微观器件性能。",
      "supplement_requests": [],
      "directed_reads": [
        {
          "source_handle": "P0002",
          "focus_area": "重点阅读关于 Figure 2d/2e 的描述及相关的数学推导部分，提取群延迟 tg(r, α) 随角度变化的非单调性证据，以及不同 NA 下带宽饱和曲线的具体形态。关注文中对 r0=Ftan(α) 与 r0=Fα 两种情况的对比讨论。",
          "integration_goal": "用于构建本章核心论点：带宽饱和的物理根源及其对传统线性预期的修正。"
        },
        {
          "source_handle": "P0001",
          "focus_area": "提取关于单层超构透镜在高 NA 下视场受限（<5 µm）的论述，以及单界面无法校正彗差和场曲的几何光学解释。",
          "integration_goal": "用于补充论证除色散限制外的第二重物理边界（几何像差），完善对 FOV 限制的全面理解。"
        }
      ]
    }
  ],
  "screened_sources": []
}

